# Parse the graph and build adjacency list
edges_text = context.split("The graph has the following edges:\n")[1].split("\n\nOperation:")[0]

graph = {}
for line in edges_text.strip().split('\n'):
    if ' -> ' in line:
        src, dst = line.split(' -> ')
        if src not in graph:
            graph[src] = []
        graph[src].append(dst)

print("Graph adjacency list:")
for k, v in graph.items():
    print(f"{k}: {v}")

start_node = "eccbc87e4b"

# BFS to find nodes at exactly depth 2
from collections import deque

visited = {start_node: 0}
queue = deque([start_node])
depths = {start_node: 0}

while queue:
    node = queue.popleft()
    current_depth = depths[node]

    if node in graph:
        for neighbor in graph[node]:
            if neighbor not in depths:
                depths[neighbor] = current_depth + 1
                queue.append(neighbor)

print(f"\nDepths from {start_node}:")
for node, depth in sorted(depths.items(), key=lambda x: x[1]):
    print(f"  {node}: depth {depth}")

depth_2_nodes = [node for node, depth in depths.items() if depth == 2]
print(f"\nNodes at exactly depth 2: {depth_2_nodes}")
```

